WITH august_orders AS (
  SELECT SUM(amount_cents) AS gross FROM orders WHERE order_date >= '2026-08-01' AND order_date < '2026-09-01'
), september_orders AS (
  SELECT SUM(amount_cents) AS gross FROM orders WHERE order_date >= '2026-09-01' AND order_date < '2026-10-01'
), august_refunds AS (
  SELECT SUM(amount_cents) AS refunds FROM refunds WHERE refund_date >= '2026-08-01' AND refund_date < '2026-09-01'
), september_refunds AS (
  SELECT SUM(amount_cents) AS refunds FROM refunds WHERE refund_date >= '2026-09-01' AND refund_date < '2026-10-01'
), base AS (
  SELECT ao.gross AS aug_gross, so.gross AS sep_gross, ar.refunds AS aug_refunds, sr.refunds AS sep_refunds,
         ao.gross-ar.refunds AS aug_net, so.gross-sr.refunds AS sep_net
  FROM august_orders ao CROSS JOIN september_orders so CROSS JOIN august_refunds ar CROSS JOIN september_refunds sr
), bridge AS (
  SELECT 1 AS step_order, 'August net' AS step, aug_net AS amount_cents FROM base
  UNION ALL SELECT 2, 'Change in gross sales', sep_gross-aug_gross FROM base
  UNION ALL SELECT 3, 'Change in refunds', aug_refunds-sep_refunds FROM base
  UNION ALL SELECT 4, 'September net', sep_net FROM base
)
SELECT step, amount_cents FROM bridge ORDER BY step_order;

WITH aug_order_totals AS (
 SELECT SUM(amount_cents) AS gross FROM orders WHERE order_date >= '2026-08-01' AND order_date < '2026-09-01'
), sep_order_totals AS (
 SELECT SUM(amount_cents) AS gross FROM orders WHERE order_date >= '2026-09-01' AND order_date < '2026-10-01'
), aug_refund_totals AS (
 SELECT SUM(amount_cents) AS refunds FROM refunds WHERE refund_date >= '2026-08-01' AND refund_date < '2026-09-01'
), sep_refund_totals AS (
 SELECT SUM(amount_cents) AS refunds FROM refunds WHERE refund_date >= '2026-09-01' AND refund_date < '2026-10-01'
), combined AS (
 SELECT ao.gross AS aug_gross, so.gross AS sep_gross, ar.refunds AS aug_refunds, sr.refunds AS sep_refunds
 FROM aug_order_totals ao CROSS JOIN sep_order_totals so CROSS JOIN aug_refund_totals ar CROSS JOIN sep_refund_totals sr
)
SELECT step, amount_cents FROM (
 SELECT 1 AS ord, 'August net' AS step, aug_gross-aug_refunds AS amount_cents FROM combined
 UNION ALL SELECT 2, 'Change in gross sales', sep_gross-aug_gross FROM combined
 UNION ALL SELECT 3, 'Change in refunds', aug_refunds-sep_refunds FROM combined
 UNION ALL SELECT 4, 'September net', sep_gross-sep_refunds FROM combined
) AS waterfall ORDER BY ord;

